    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collEmailAttachments) {
                foreach ($this->collEmailAttachments as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTransferencias) {
                foreach ($this->collTransferencias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collEmailUsuarios) {
                foreach ($this->collEmailUsuarios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collEmailBitacoras) {
                foreach ($this->collEmailBitacoras as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aEmailAccount instanceof Persistent) {
              $this->aEmailAccount->clearAllReferences($deep);
            }
            if ($this->aEmailEstado instanceof Persistent) {
              $this->aEmailEstado->clearAllReferences($deep);
            }
            if ($this->aUsuario instanceof Persistent) {
              $this->aUsuario->clearAllReferences($deep);
            }
            if ($this->aModulo instanceof Persistent) {
              $this->aModulo->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collEmailAttachments instanceof PropelCollection) {
            $this->collEmailAttachments->clearIterator();
        }
        $this->collEmailAttachments = null;
        if ($this->collTransferencias instanceof PropelCollection) {
            $this->collTransferencias->clearIterator();
        }
        $this->collTransferencias = null;
        if ($this->collEmailUsuarios instanceof PropelCollection) {
            $this->collEmailUsuarios->clearIterator();
        }
        $this->collEmailUsuarios = null;
        if ($this->collEmailBitacoras instanceof PropelCollection) {
            $this->collEmailBitacoras->clearIterator();
        }
        $this->collEmailBitacoras = null;
        $this->aEmailAccount = null;
        $this->aEmailEstado = null;
        $this->aUsuario = null;
        $this->aModulo = null;
    }

